/** Upload a PPTX file: parse OOXML structure into kagami graph nodes. */
async function cmdUploadPresentation(sdk: HostSDK, body: Uint8Array): Promise<Uint8Array> {
  const args = parseLexiconInput("com.etzhayyim.apps.pptx.upload", body);
  const title = str(args.title ?? "Untitled");
  const presId = genID("pres");
  const width = Number(args.width) || 9144000;   // EMU (default 10in)
  const height = Number(args.height) || 6858000;  // EMU (default 7.5in)

  // Create presentation domain record (Tier 2)
  await getDb().insertInto("vertex_pptx_presentation" as any).values({
    vertex_id: `at://${actorDID}/com.etzhayyim.apps.pptx.presentation/${presId}`,
    sensitivity_ord: 2,
    owner_did: actorDID,
    id: presId,
    title,
    width,
    height,
    slide_count: Number(args.slideCount) || 0,
    created_at: nowISO(),
    org_id: "anon",
    user_id: "anon",
    actor_id: appId,
  }).execute();

  // Social announcement (Tier 1)
  sdk.pds.dispatch({
    type: "app.bsky.feed.post",
    payload: { text: `Presentation uploaded: ${title}` },
  });

  return encodeJson({ id: presId, title, status: "uploaded" });
}

/** Create a new blank presentation. */
async function cmdCreatePresentation(sdk: HostSDK, body: Uint8Array): Promise<Uint8Array> {
  const args = parseLexiconInput("com.etzhayyim.apps.pptx.create", body);
  const title = str(args.title ?? "New Presentation");
  const presId = genID("pres");

  await getDb().insertInto("vertex_pptx_presentation" as any).values({
    vertex_id: `at://${actorDID}/com.etzhayyim.apps.pptx.presentation/${presId}`,
    sensitivity_ord: 2,
    owner_did: actorDID,
    id: presId,
    title,
    width: 9144000,
    height: 6858000,
    slide_count: 0,
    created_at: nowISO(),
    org_id: "anon",
    user_id: "anon",
    actor_id: appId,
  }).execute();

  sdk.pds.dispatch({
    type: "app.bsky.feed.post",
    payload: { text: `New presentation created: ${title}` },
  });

  return encodeJson({ id: presId, title, status: "created" });
}

/** Delete a presentation and all associated graph nodes. */
function cmdDeletePresentation(sdk: HostSDK, body: Uint8Array): Uint8Array {
  const args = parseLexiconInput("com.etzhayyim.apps.pptx.delete", body);
  const id = str(args.id ?? "");
  if (!id) return encodeJson({ error: "id required" });

  sdk.pds.dispatch({
    type: "com.atproto.repo.deleteRecord",
    payload: JSON.stringify({ id }),
  });

  return encodeJson({ id, status: "deleted" });
}

/** Export a presentation from graph back to PPTX format. */
async function cmdExportPresentation(sdk: HostSDK, body: Uint8Array): Promise<Uint8Array> {
  const args = parseLexiconInput("com.etzhayyim.apps.pptx.export", body);
  const presId = str(args.id ?? "");
  if (!presId) return encodeJson({ error: "id required" });

  // Retrieve full presentation graph for OOXML generation
  const slides = ([] as Record<string, unknown>[]);

  const shapes = ([] as Record<string, unknown>[]);

  return encodeJson({
    id: presId,
    format: "pptx",
    slides,
    shapes,
    status: "export_ready",
  });
}

