/** Update shape properties (position, size, rotation, fill, stroke). */
function cmdUpdateShape(sdk: HostSDK, body: Uint8Array): Uint8Array {
  const args = parseLexiconInput("com.etzhayyim.apps.pptx.updateShape", body);
  const id = str(args.id ?? "");
  if (!id) return encodeJson({ error: "id required" });

  sdk.pds.dispatch({
    type: "com.atproto.repo.putRecord",
    payload: JSON.stringify({
      id,
      ...(args.x !== undefined && { x: Number(args.x) }),
      ...(args.y !== undefined && { y: Number(args.y) }),
      ...(args.w !== undefined && { w: Number(args.w) }),
      ...(args.h !== undefined && { h: Number(args.h) }),
      ...(args.rotation !== undefined && { rotation: Number(args.rotation) }),
      ...(args.fill !== undefined && { fill: args.fill }),
      ...(args.stroke !== undefined && { stroke: args.stroke }),
    }),
  });

  return encodeJson({ id, status: "updated" });
}

