/** Create a multi-slide presentation from multiple image blob references. */
async function cmdCreateFromImages(sdk: HostSDK, body: Uint8Array): Promise<Uint8Array> {
  const args = parseLexiconInput("com.etzhayyim.apps.pptx.createFromImages", body);
  const images: { blobCid: string; mime?: string }[] = args.images ?? [];
  const title = str(args.title ?? "Image Presentation");
  if (images.length === 0) return encodeJson({ error: "images array required" });
  const presId = genID("pres");
  await getDb().insertInto("vertex_pptx_presentation" as any).values({
    vertex_id: `at://${actorDID}/com.etzhayyim.apps.pptx.presentation/${presId}`,
    sensitivity_ord: 2,
    owner_did: actorDID,
    id: presId,
    title,
    width: 9144000,
    height: 6858000,
    slide_count: images.length,
    created_at: nowISO(),
    org_id: "anon",
    user_id: "anon",
    actor_id: appId,
  }).execute();
  const slideIds: string[] = [];
  for (let i = 0; i < images.length; i++) {
    const slideId = genID("slide");
    const imageId = genID("img");
    slideIds.push(slideId);
    await getDb().insertInto("vertex_pptx_slide" as any).values({
      vertex_id: `at://${actorDID}/com.etzhayyim.apps.pptx.slide/${slideId}`,
      sensitivity_ord: 2,
      owner_did: actorDID,
      id: slideId,
      presentation_id: presId,
      order: i,
      layout_ref: "blank",
      created_at: nowISO(),
      org_id: "anon",
      user_id: "anon",
      actor_id: appId,
    }).execute();
    await getDb().insertInto("vertex_pptx_image" as any).values({
      vertex_id: `at://${actorDID}/com.etzhayyim.apps.pptx.image/${imageId}`,
      sensitivity_ord: 2,
      owner_did: actorDID,
      id: imageId,
      slide_id: slideId,
      blob_cid: images[i].blobCid,
      mime: images[i].mime ?? "image/png",
      x: 457200,
      y: 457200,
      w: 8229600,
      h: 5943600,
      created_at: nowISO(),
      org_id: "anon",
      user_id: "anon",
      actor_id: appId,
    }).execute();
  }
  return encodeJson({ id: presId, title, slideCount: images.length, slideIds, status: "created" });
}

