/** Extract all text from all slides of a presentation (for LLM summarization). */
async function cmdExtractAllText(sdk: HostSDK, body: Uint8Array): Promise<Uint8Array> {
  const args = parseLexiconInput("com.etzhayyim.apps.pptx.extractAllText", body);
  const presId = str(args.presentationId ?? "");
  if (!presId) return encodeJson({ error: "presentationId required" });
  const raw = ([] as Record<string, unknown>[]);
  const slideTexts: Record<number, string[]> = {};
  for (const row of raw) { const o = Number(row.slideOrder ?? 0); if (!slideTexts[o]) slideTexts[o] = []; slideTexts[o].push(str(row.text ?? "")); }
  const fullText = Object.entries(slideTexts).sort(([a], [b]) => Number(a) - Number(b)).map(([o, t]) => `--- Slide ${Number(o) + 1} ---\n${t.join(" ")}`).join("\n\n");
  return encodeJson({ presentationId: presId, text: fullText, slideCount: Object.keys(slideTexts).length });
}

