/** Ensure a sub-DID exists for the given path. */
function ensureSubDid(sdk: HostSDK, path: string, displayName: string): string {
  return str(sdk.hostImports.comAtprotoIdentityCreate(
    path, JSON.stringify({ displayName, description: `${displayName} — sub-DID of PPTX Editor` }),
  ));
}

