function editorHTML(): string {
  return new TextDecoder().decode(Uint8Array.from(atob(EDITOR_HTML_B64), c => c.charCodeAt(0)));
}

export default createWorkerExport((sdk) => {
  appId = sdk.pds.selfNanoid ?? "";
  actorDID = sdk.pds.selfRepo ?? "";

  // Serve editor HTML from /embed (embed mode)
  sdk.router.get("/embed", (c) => c.html(editorHTML(), 200, { "Access-Control-Allow-Origin": "*" }));
  // Serve editor HTML from /editor (direct access, no embed query)
  sdk.router.get("/editor", (c) => c.html(editorHTML()));
  sdk.app
    // Presentation Management
    .command(nsid("com.etzhayyim.apps.pptx.upload"), (ctx, body) => cmdUploadPresentation(sdk, body),
      asAgentTool("Upload and parse PPTX file"),
      withCapabilityTags("write", "pptx", "upload"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.create"), (ctx, body) => cmdCreatePresentation(sdk, body),
      asAgentTool("Create new blank presentation"),
      withCapabilityTags("write", "pptx"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.delete"), (ctx, body) => cmdDeletePresentation(sdk, body),
      asAgentTool("Delete a presentation"),
      withCapabilityTags("write", "pptx"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.export"), (ctx, body) => cmdExportPresentation(sdk, body),
      asAgentTool("Export presentation to PPTX"),
      withCapabilityTags("export", "pptx"),
    )
    // Slide Editing
    .command(nsid("com.etzhayyim.apps.pptx.addSlide"), (ctx, body) => cmdAddSlide(sdk, body),
      asAgentTool("Add slide to presentation"),
      withCapabilityTags("write", "pptx", "slide"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.removeSlide"), (ctx, body) => cmdRemoveSlide(sdk, body),
      asAgentTool("Remove slide from presentation"),
      withCapabilityTags("write", "pptx", "slide"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.reorderSlides"), (ctx, body) => cmdReorderSlides(sdk, body),
      asAgentTool("Reorder slides"),
      withCapabilityTags("write", "pptx", "slide"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.addShape"), (ctx, body) => cmdAddShape(sdk, body),
      asAgentTool("Add shape to slide"),
      withCapabilityTags("write", "pptx", "shape"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.updateShape"), (ctx, body) => cmdUpdateShape(sdk, body),
      asAgentTool("Update shape properties"),
      withCapabilityTags("write", "pptx", "shape"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.removeShape"), (ctx, body) => cmdRemoveShape(sdk, body),
      asAgentTool("Remove shape from slide"),
      withCapabilityTags("write", "pptx", "shape"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.editText"), (ctx, body) => cmdEditText(sdk, body),
      asAgentTool("Edit text in shape"),
      withCapabilityTags("write", "pptx", "text"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.addImage"), (ctx, body) => cmdAddImage(sdk, body),
      asAgentTool("Add image to slide"),
      withCapabilityTags("write", "pptx", "image"),
    )
    // Search & Query
    .command(nsid("com.etzhayyim.apps.pptx.search"), (ctx, body) => cmdSearchPresentations(sdk, body),
      asAgentTool("Search presentations"),
      withCapabilityTags("search", "pptx"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.listSlides"), (ctx, body) => cmdListSlides(sdk, body),
      asAgentTool("List slides in presentation"),
      withCapabilityTags("query", "pptx", "slide"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.getSlideElements"), (ctx, body) => cmdGetSlideElements(sdk, body),
      asAgentTool("Get slide elements"),
      withCapabilityTags("query", "pptx", "slide"),
    )
    // Image Conversion (img2pptx consolidated)
    .command(nsid("com.etzhayyim.apps.pptx.convertImage"), (ctx, body) => cmdConvertImage(sdk, body),
      asAgentTool("Convert image to slide shape"),
      withCapabilityTags("write", "pptx", "image-conversion"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.convertSvg"), (ctx, body) => cmdConvertSvg(sdk, body),
      asAgentTool("Convert SVG to DrawingML shapes"),
      withCapabilityTags("write", "pptx", "svg-conversion"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.createFromImages"), (ctx, body) => cmdCreateFromImages(sdk, body),
      asAgentTool("Create presentation from multiple images"),
      withCapabilityTags("write", "pptx", "batch-conversion"),
    )
    // Content Extraction (mime-pptx consolidated)
    .command(nsid("com.etzhayyim.apps.pptx.extractAllText"), (ctx, body) => cmdExtractAllText(sdk, body),
      asAgentTool("Extract all text from presentation"),
      withCapabilityTags("query", "pptx", "text-extraction"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.searchText"), (ctx, body) => cmdSearchText(sdk, body),
      asAgentTool("Full-text search across slides"),
      withCapabilityTags("search", "pptx", "text-search"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.getMetadata"), (ctx, body) => cmdGetMetadata(sdk, body),
      asAgentTool("Get presentation metadata"),
      withCapabilityTags("query", "pptx", "metadata"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.getSlide"), (ctx, body) => cmdGetSlide(sdk, body),
      asAgentTool("Get slide with text and image refs"),
      withCapabilityTags("query", "pptx", "slide-extraction"),
    )
    // Utility
    .command(nsid("com.etzhayyim.apps.pptx.health"), (ctx, body) => cmdHealth(sdk, body),
      asAgentTool("PPTX health check"),
      withCapabilityTags("diagnostics", "pptx"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.describe"), (ctx, body) => cmdDescribe(sdk, body),
      asAgentTool("Describe PPTX capabilities"),
      withCapabilityTags("meta", "pptx"),
    )
    .command(nsid("com.etzhayyim.apps.pptx.wave"), (ctx, body) => cmdWave(sdk, body),
      asAgentTool("Respond to wave greeting"),
      withCapabilityTags("social", "greeting"),
    );
});
